# ============================================================
# SRT PARSER
# ============================================================

def parse_srt(path):

    with open(
        path,
        "r",
        encoding="utf-8-sig"
    ) as f:

        content = f.read()

    blocks = re.split(
        r"\n\s*\n",
        content.strip()
    )

    subtitles = []

    for block in blocks:

        lines = block.strip().splitlines()

        if len(lines) < 3:
            continue

        try:
            index = int(
                lines[0].strip()
            )
        except ValueError:
            continue

        timecode = lines[1].strip()

        text = "\n".join(
            lines[2:]
        ).strip()

        subtitles.append({
            "index": index,
            "timecode": timecode,
            "source": text
        })

    return subtitles


# ============================================================
# EXISTING SRT
# ============================================================

def parse_existing_srt(path):

    if not os.path.exists(path):
        return {}

    with open(
        path,
        "r",
        encoding="utf-8-sig"
    ) as f:

        content = f.read()

    blocks = re.split(
        r"\n\s*\n",
        content.strip()
    )

    result = {}

    for block in blocks:

        lines = block.strip().splitlines()

        if len(lines) < 3:
            continue

        try:
            index = int(
                lines[0].strip()
            )
        except ValueError:
            continue

        timecode = lines[1].strip()

        text = "\n".join(
            lines[2:]
        ).strip()

        result[index] = {
            "index": index,
            "timecode": timecode,
            "translation": text
        }

    return result


# ============================================================
# SINGLE JSON PARSER
# ============================================================

def extract_translation(
    response_text,
    expected_id
):
    """
    อ่าน JSON จาก Ollama

    Expected:

    {
        "id": 1,
        "translation": "...",
        "confidence": 0.95
    }
    """

    try:

        data = json.loads(
            response_text
        )

        returned_id = int(
            data["id"]
        )

        print(
            f"   🆔 EXPECTED ID: {expected_id} | RETURNED ID: {returned_id}"
        )

        if returned_id != expected_id:

            print(
                f"   ⚠️ ID mismatch: "
                f"expected {expected_id}, "
                f"got {returned_id}"
            )

            return None

        translation = str(
            data["translation"]
        ).strip()

        if not translation:

            print(
                "   ⚠️ Empty translation"
            )

            return None

        confidence = float(
            data.get(
                "confidence",
                0
            )
        )

        confidence = max(
            0.0,
            min(1.0, confidence)
        )

        return {
            "translation": translation,
            "confidence": confidence
        }

    except json.JSONDecodeError as e:

        print(
            f"   ⚠️ JSON parse error: {e}"
        )

        print(
            f"   RAW: {response_text}"
        )

        return None

    except Exception as e:

        print(
            f"   ⚠️ Parse error: {e}"
        )

        print(
            f"   RAW: {response_text}"
        )

        return None


# ============================================================
# BATCH JSON PARSER
# ============================================================

def extract_batch_translations(
    response_text,
    expected_ids
):
    """
    อ่าน JSON batch จาก Ollama

    Expected:

    {
        "translations": [
            {
                "id": 1,
                "translation": "...",
                "confidence": 0.95
            }
        ]
    }
    """

    try:

        data = json.loads(
            response_text
        )

        translations_list = data[
            "translations"
        ]

        if not isinstance(
            translations_list,
            list
        ):

            print(
                "   ⚠️ translations "
                "is not a list"
            )

            return None

        results = {}

        for item in translations_list:

            idx = int(
                item["id"]
            )

            translation = str(
                item["translation"]
            ).strip()

            confidence = float(
                item.get(
                    "confidence",
                    0
                )
            )

            confidence = max(
                0.0,
                min(1.0, confidence)
            )

            if not translation:

                print(
                    f"   ⚠️ Empty translation: "
                    f"{idx}"
                )

                return None

            # ตรวจ duplicate ID
            if idx in results:

                print(
                    f"   ⚠️ Duplicate ID: "
                    f"{idx}"
                )

                return None

            results[idx] = {
                "translation": translation,
                "confidence": confidence
            }

        expected_ids = set(
            expected_ids
        )

        returned_ids = set(
            results.keys()
        )

        # ตรวจ subtitle หาย
        missing_ids = (
            expected_ids
            - returned_ids
        )

        if missing_ids:

            print(
                f"   ⚠️ Missing IDs: "
                f"{sorted(missing_ids)}"
            )

            return None

        # ตรวจ subtitle เกิน
        extra_ids = (
            returned_ids
            - expected_ids
        )

        if extra_ids:

            print(
                f"   ⚠️ Unexpected IDs: "
                f"{sorted(extra_ids)}"
            )

            return None

        return results

    except json.JSONDecodeError as e:

        print(
            f"   ⚠️ Batch JSON parse error: "
            f"{e}"
        )

        print(
            f"   RAW:\n{response_text}"
        )

        return None

    except Exception as e:

        print(
            f"   ⚠️ Batch parse error: "
            f"{e}"
        )

        print(
            f"   RAW:\n{response_text}"
        )

        return None
# ============================================================
# QUALITY CHECKER
# ============================================================

def contains_chinese(text):
    """
    ตรวจว่ามีอักษรจีนหลงเหลืออยู่หรือไม่
    """

    if not text:
        return False

    chinese_pattern = re.compile(
        r"[\u3400-\u4DBF\u4E00-\u9FFF\uF900-\uFAFF]"
    )

    return bool(
        chinese_pattern.search(text)
    )


def check_translation_quality(
    item,
    result
):
    """
    ตรวจคุณภาพคำแปลเบื้องต้น

    Return:
        {
            "needs_review": True/False,
            "reasons": [...]
        }
    """

    reasons = []

    if not result:

        reasons.append(
            "ไม่มีผลการแปล"
        )

        return {
            "needs_review": True,
            "reasons": reasons
        }

    translation = str(
        result.get(
            "translation",
            ""
        )
    ).strip()

    confidence = float(
        result.get(
            "confidence",
            0
        )
    )

    # --------------------------------------------------------
    # 1. Empty translation
    # --------------------------------------------------------

    if not translation:

        reasons.append(
            "คำแปลว่าง"
        )

    # --------------------------------------------------------
    # 2. Chinese remains
    # --------------------------------------------------------

    elif contains_chinese(
        translation
    ):

        reasons.append(
            "พบภาษาจีนหลงเหลือในคำแปล"
        )

    # --------------------------------------------------------
    # 3. Low confidence
    # --------------------------------------------------------

    if confidence < CONFIDENCE_THRESHOLD:

        reasons.append(
            f"confidence ต่ำ "
            f"({confidence:.2f})"
        )

    # --------------------------------------------------------
    # 4. Abnormally long
    # --------------------------------------------------------

    if len(translation) > MAX_TRANSLATION_LENGTH:

        reasons.append(
            f"คำแปลยาวผิดปกติ "
            f"({len(translation)} ตัวอักษร)"
        )

    # --------------------------------------------------------
    # Result
    # --------------------------------------------------------

    return {
        "needs_review": len(reasons) > 0,
        "reasons": reasons
    }

# ============================================================
# ADD REVIEW RESULT
# ============================================================

def add_review_item(
    review_items,
    item,
    result,
    quality
):

    review_items.append({
        "index": item["index"],
        "timecode": item["timecode"],
        "source": item["source"],
        "translation": (
            result["translation"]
            if result
            else ""
        ),
        "confidence": (
            result["confidence"]
            if result
            else 0
        ),
        "reasons": quality[
            "reasons"
        ]
    })

# ============================================================
# WRITE REVIEW SRT
# ============================================================

def write_review_srt(
    path,
    review_items
):

    with open(
        path,
        "w",
        encoding="utf-8"
    ) as f:

        for item in review_items:

            f.write(
                f"{item['index']}\n"
            )

            f.write(
                f"{item['timecode']}\n"
            )

            # ใช้คำแปลก่อน
            # เพื่อให้เปิดดูใน player ได้
            translation = (
                item["translation"]
                if item["translation"]
                else "[ต้องตรวจสอบ]"
            )

            f.write(
                f"{translation}\n"
            )

            # เพิ่มข้อมูลสาเหตุในบรรทัดถัดไป
            f.write(
                f"[REVIEW: "
                f"{'; '.join(item['reasons'])}]\n\n"
            )    
# ============================================================
# CALL OLLAMA
# ============================================================

def call_ollama(
    prompt,
    num_predict=2048
):

    payload = {

        "model": MODEL_NAME,

        "messages": [
            {
                "role": "system",
                "content": SYSTEM_PROMPT
            },
            {
                "role": "user",
                "content": prompt
            }
        ],

        "stream": False,

        # ปิด thinking
        "think": False,

        # บังคับ JSON
        "format": "json",

        "options": {
            "temperature": 0.1,
            "num_ctx": 4096,
            "num_predict": num_predict
        },

        "keep_alive": "10m"
    }

    try:

        response = requests.post(
            OLLAMA_URL,
            json=payload,
            timeout=300
        )

        response.raise_for_status()

        data = response.json()

        content = data.get(
            "message",
            {}
        ).get(
            "content",
            ""
        )

        return content.strip()

    except requests.exceptions.RequestException as e:

        print(
            f"   ❌ Ollama request error: "
            f"{e}"
        )

        return None

    except Exception as e:

        print(
            f"   ❌ Ollama error: {e}"
        )

        return None


# ============================================================
# TRANSLATION MEMORY
# ============================================================

def load_translation_memory():
    """
    โหลด Translation Memory ที่สร้างโดย comparator_training_fixed.py

    Memory ใช้ข้อมูล Source -> Gold ที่ผ่านการเปรียบเทียบแล้ว
    และ AI ของ comparator มีหน้าที่จัด category เท่านั้น

    รองรับ field:
        source
        target
        category
        count

    เพื่อ backward compatibility ยังรองรับ:
        source_zh
        target_th
    """

    if not os.path.exists(MEMORY_FILE):
        print(
            "ℹ️ ไม่พบ Translation Memory: "
            f"{MEMORY_FILE}"
        )
        return []

    memory = []
    seen = set()

    try:
        with open(
            MEMORY_FILE,
            "r",
            encoding="utf-8-sig"
        ) as f:

            for line in f:
                line = line.strip()

                if not line:
                    continue

                try:
                    item = json.loads(line)
                except json.JSONDecodeError:
                    continue

                source = str(
                    item.get(
                        "source",
                        item.get("source_zh", "")
                    )
                ).strip()

                target = str(
                    item.get(
                        "target",
                        item.get("target_th", "")
                    )
                ).strip()

                if not source or not target:
                    continue

                key = (
                    source.casefold(),
                    target.casefold()
                )

                # ป้องกัน memory ซ้ำ
                if key in seen:
                    continue

                seen.add(key)

                category = str(
                    item.get(
                        "category",
                        "other"
                    )
                ).strip().lower()

                if not category:
                    category = "other"

                try:
                    count = int(
                        item.get(
                            "count",
                            1
                        )
                    )
                except (TypeError, ValueError):
                    count = 1

                memory.append({
                    "source_zh": source,
                    "target_th": target,
                    "category": category,
                    "count": max(1, count),
                })

    except Exception as e:
        print(
            f"⚠️ โหลด Translation Memory ไม่สำเร็จ: {e}"
        )
        return []

    print(
        f"🧠 Translation Memory loaded: "
        f"{len(memory)} examples"
    )

    # แสดงจำนวน category เพื่อ debug
    category_counts = {}

    for item in memory:
        category = item.get(
            "category",
            "other"
        )

        category_counts[category] = (
            category_counts.get(category, 0) + 1
        )

    if category_counts:
        print(
            "   Categories: "
            + ", ".join(
                f"{k}={v}"
                for k, v in sorted(
                    category_counts.items()
                )
            )
        )

    return memory


def find_relevant_memory(
    source_text,
    memory,
    max_examples=MAX_MEMORY_EXAMPLES
):
    """
    หา Memory ที่เกี่ยวข้องกับ subtitle ปัจจุบัน

    ลำดับความสำคัญ:
    1. Exact match
    2. Source ที่คล้ายกันด้วย SequenceMatcher
    3. count สูงช่วยดัน memory ที่พบซ้ำบ่อยขึ้นเล็กน้อย

    AI ไม่ได้สร้างคำแปลจาก Memory
    แต่ได้รับ Source -> Gold ที่มนุษย์ยอมรับแล้วเป็น reference
    """

    if not memory or not source_text:
        return []

    source_text = source_text.strip()

    if not source_text:
        return []

    scored = []

    for item in memory:

        memory_source = item.get(
            "source_zh",
            ""
        ).strip()

        memory_target = item.get(
            "target_th",
            ""
        ).strip()

        if not memory_source or not memory_target:
            continue

        # Exact match
        if source_text == memory_source:
            similarity = 1.0
            exact = True
        else:
            similarity = SequenceMatcher(
                None,
                source_text,
                memory_source
            ).ratio()
            exact = False

        if exact or similarity >= MEMORY_MIN_SIMILARITY:

            try:
                count = int(
                    item.get(
                        "count",
                        1
                    )
                )
            except (TypeError, ValueError):
                count = 1

            # count มีผลเพียงเล็กน้อย
            # ไม่ให้ memory ที่เจอบ่อย override similarity
            score = (
                similarity
                + (MEMORY_EXACT_BONUS if exact else 0)
                + min(count, 20) * MEMORY_COUNT_BONUS
            )

            scored.append({
                "score": score,
                "similarity": similarity,
                "source_zh": memory_source,
                "target_th": memory_target,
                "category": item.get(
                    "category",
                    "other"
                ),
                "count": count,
                "exact": exact,
            })

    scored.sort(
        key=lambda x: (
            x["exact"],
            x["score"],
            x["similarity"],
            x["count"],
        ),
        reverse=True
    )

    return scored[:max_examples]


def build_memory_context_for_items(
    items,
    memory,
    max_examples=MAX_MEMORY_EXAMPLES
):
    """
    สำหรับ batch translation:
    รวม Memory ของทุก subtitle ใน batch
    แล้วตัดเหลือเฉพาะรายการที่เกี่ยวข้องที่สุด
    """

    if not memory:
        return []

    candidates = []
    seen = set()

    for item in items:

        relevant = find_relevant_memory(
            item.get(
                "source",
                ""
            ),
            memory,
            max_examples=max_examples
        )

        for mem in relevant:

            key = (
                mem["source_zh"],
                mem["target_th"]
            )

            if key in seen:
                continue

            seen.add(key)
            candidates.append(mem)

    candidates.sort(
        key=lambda x: (
            x["exact"],
            x["score"],
            x["similarity"],
            x["count"],
        ),
        reverse=True
    )

    return candidates[:max_examples]


def format_memory_context(memory_examples):
    """
    สร้างข้อความ Memory สำหรับส่งให้ Qwen

    สำคัญ:
    - บอกชัดว่าเป็นคำแปล Gold จากฐานข้อมูล
    - ห้าม copy แบบไม่ดูบริบท
    - category เป็น metadata ช่วยให้โมเดลเข้าใจชนิดของ memory
    """

    if not memory_examples:
        return ""

    lines = [
        "Translation Memory จากคำแปล Gold ที่ผ่านการตรวจสอบแล้ว:",
        ""
    ]

    for mem in memory_examples:

        category = mem.get(
            "category",
            "other"
        )

        count = mem.get(
            "count",
            1
        )

        lines.append(
            f"- [{category}] "
            f"จีน: {mem['source_zh']}"
        )

        lines.append(
            f"  ไทย: {mem['target_th']} "
            f"(พบ {count} ครั้ง)"
        )

    lines.append("")
    lines.append(
        "กฎการใช้ Translation Memory:"
    )
    lines.append(
        "- ใช้เป็น reference สำหรับชื่อบุคคล "
        "ศัพท์เฉพาะ สำนวน และรูปแบบการแปล"
    )
    lines.append(
        "- ถ้า source ปัจจุบันตรงกับ Memory "
        "ให้ใช้คำแปล Gold นั้นเป็นหลัก"
    )
    lines.append(
        "- ถ้า source ไม่ตรงกัน ให้ดูบริบทก่อน "
        "และห้ามยัดคำแปลจาก Memory แบบฝืนความหมาย"
    )
    lines.append(
        "- ห้ามเปิดเผยหรืออธิบาย Translation Memory "
        "ในคำตอบ"
    )
    lines.append("")

    return "\n".join(lines)


# ============================================================
# MAKE SINGLE PROMPT
# ============================================================

def make_prompt(
    item,
    previous_context=None,
    memory=None
):

    prompt = ""

    if previous_context:

        prompt += (
            "บริบท subtitle ก่อนหน้า:\n"
        )

        for ctx in previous_context:

            prompt += (
                f"[{ctx['index']}] "
                f"{ctx['source']}\n"
            )

        prompt += "\n"

    # --------------------------------------------------------
    # TRANSLATION MEMORY
    # --------------------------------------------------------

    if memory:

        relevant_memory = find_relevant_memory(
            item["source"],
            memory
        )

        if relevant_memory:
            prompt += format_memory_context(
                relevant_memory
            )

    prompt += (
        "แปล subtitle ต่อไปนี้:\n\n"
    )

    prompt += (
        f"[{item['index']}] "
        f"{item['source']}\n\n"
    )

    prompt += f"""
IMPORTANT: subtitle ID นี้คือ {item["index"]}
ต้องคืน ID เป็น {item["index"]} เท่านั้น ห้ามเปลี่ยนเป็น 1 หรือเลขอื่น

ตอบเป็น JSON เท่านั้น:

{{
  "id": {item["index"]},
  "translation": "คำแปลภาษาไทย",
  "confidence": 0.95
}}
"""

    return prompt


# ============================================================
# MAKE BATCH PROMPT
# ============================================================

def make_batch_prompt(
    items,
    previous_context=None,
    memory=None
):

    prompt = ""

    if previous_context:

        prompt += (
            "บริบท subtitle ก่อนหน้า:\n"
        )

        for ctx in previous_context:

            prompt += (
                f"[{ctx['index']}] "
                f"{ctx['source']}\n"
            )

        prompt += "\n"

    # --------------------------------------------------------
    # TRANSLATION MEMORY
    # --------------------------------------------------------

    memory_examples = build_memory_context_for_items(
        items,
        memory
    )

    if memory_examples:
        prompt += format_memory_context(
            memory_examples
        )

    prompt += (
        "แปล subtitle ต่อไปนี้ทั้งหมด:\n\n"
    )

    for item in items:

        prompt += (
            f"[{item['index']}] "
            f"{item['source']}\n"
        )

    expected_ids = [item["index"] for item in items]
    expected_text = ", ".join(str(x) for x in expected_ids)

    example_items = []
    for item in items:
        example_items.append(
            "    {\n"
            f"      \"id\": {item['index']},\n"
            "      \"translation\": \"คำแปลภาษาไทย\",\n"
            "      \"confidence\": 0.95\n"
            "    }"
        )
    json_example = ",\n".join(example_items)

    prompt += f"""

ต้องแปล subtitle ทุกหมายเลข

IMPORTANT — ID ห้ามเปลี่ยนเด็ดขาด:
- ID ที่ส่งเข้ามาคือ: [{expected_text}]
- ต้องคืน ID เดิม EXACTLY ตามรายการข้างต้น
- ห้ามเปลี่ยนเป็น 1, 2, 3 หรือสร้างเลขใหม่
- ห้ามเรียงเลขใหม่
- ห้ามข้าม ID
- ห้ามเพิ่ม ID ที่ไม่มีใน input

ห้าม:
- ข้าม subtitle
- เพิ่ม subtitle
- รวม subtitle
- เปลี่ยน ID
- ใส่คำอธิบาย
- ใส่ Markdown
- ใส่ timestamp
- ใส่ข้อความนอก JSON

ตอบ JSON ตามรูปแบบนี้เท่านั้น และใช้ ID จริงจาก input:

{{
  "translations": [
{json_example}
  ]
}}
"""

    return prompt



# ============================================================
# MEMORY-FIRST ENGINE
# ============================================================

def find_exact_memory(source_text, memory):
    """คืนค่า Memory ที่ source ตรงกับ subtitle ทั้งประโยค"""
    if not source_text or not memory:
        return None

    source_text = source_text.strip()
    matches = []

    for item in memory:
        mem_source = str(item.get("source_zh", item.get("source", ""))).strip()
        mem_target = str(item.get("target_th", item.get("target", ""))).strip()

        if not mem_source or not mem_target:
            continue

        if source_text == mem_source:
            try:
                count = int(item.get("count", 1))
            except (TypeError, ValueError):
                count = 1

            matches.append({
                "source_zh": mem_source,
                "target_th": mem_target,
                "category": item.get("category", "other"),
                "count": count,
            })

    if not matches:
        return None

    matches.sort(key=lambda x: x["count"], reverse=True)
    return matches[0]


def lock_memory_terms(source_text, memory):
    """
    ล็อกคำ/ชื่อ/ศัพท์จาก Memory ที่อยู่ภายใน subtitle
    โดยแทนด้วย [[TM0]], [[TM1]], ...
    """
    if not source_text or not memory:
        return source_text, []

    text = source_text
    candidates = []

    for item in memory:
        source = str(item.get("source_zh", item.get("source", ""))).strip()
        target = str(item.get("target_th", item.get("target", ""))).strip()

        if not source or not target:
            continue

        if source in text:
            try:
                count = int(item.get("count", 1))
            except (TypeError, ValueError):
                count = 1

            candidates.append({
                "source": source,
                "target": target,
                "category": item.get("category", "other"),
                "count": count,
            })

    # คำยาวกว่ามาก่อน เพื่อป้องกันกรณี
    # 中国 กับ 中国大陆
    candidates.sort(
        key=lambda x: (len(x["source"]), x["count"]),
        reverse=True
    )

    locks = []
    used_sources = set()

    for candidate in candidates:
        source = candidate["source"]

        if source in used_sources or source not in text:
            continue

        placeholder = f"[[TM{len(locks)}]]"
        text = text.replace(source, placeholder)

        locks.append({
            "placeholder": placeholder,
            "source": source,
            "target": candidate["target"],
            "category": candidate["category"],
            "count": candidate["count"],
        })

        used_sources.add(source)

    return text, locks


def restore_memory_terms(translation, locks):
    """แทน placeholder กลับเป็นคำแปล Gold จาก Memory"""
    if not translation or not locks:
        return translation

    result = translation

    for lock in locks:
        result = result.replace(
            lock["placeholder"],
            lock["target"]
        )

    return result


def validate_locked_terms(translation, locks):
    """
    ตรวจว่า AI รักษา placeholder ครบหรือไม่
    ถ้าหายไป จะไม่ยอมรับผลลัพธ์นั้น
    """
    if not locks:
        return True

    if not translation:
        return False

    return all(
        lock["placeholder"] in translation
        for lock in locks
    )


def make_memory_lock_prompt(locks):
    """สร้างกฎสำหรับ placeholder ที่ถูกล็อก"""
    if not locks:
        return ""

    lines = [
        "",
        "=== LOCKED TRANSLATION MEMORY ===",
        "คำต่อไปนี้มาจาก Translation Memory ที่ผ่านการตรวจสอบแล้ว",
        "ห้ามแปลใหม่ ห้ามเปลี่ยน และห้ามลบ placeholder",
        "",
    ]

    for lock in locks:
        lines.append(
            f"{lock['placeholder']} = {lock['target']}"
        )

    lines.extend([
        "",
        "กฎ:",
        "1. ต้องคง placeholder ทุกตัวไว้ในคำตอบ",
        "2. ห้ามแปล placeholder เป็นภาษาอื่น",
        "3. ห้ามลบ placeholder",
        "4. ห้ามเปลี่ยนหมายเลขของ placeholder",
        "5. ระบบ Python จะนำคำแปล Gold กลับมาแทนภายหลัง",
        "",
    ])

    return "\n".join(lines)

# ============================================================
# TRANSLATE SINGLE
# ============================================================

def translate_single(
    item,
    previous_context=None,
    memory=None
):
    source = item["source"]

    # ========================================================
    # 1. EXACT MEMORY
    # ========================================================

    exact = find_exact_memory(
        source,
        memory
    )

    if exact:
        print(
            f"   🧠 MEMORY EXACT "
            f"[{item['index']}] "
            f"{source} → {exact['target_th']}"
        )

        return {
            "translation": exact["target_th"],
            "confidence": 1.0,
            "memory": True,
            "memory_type": "exact",
        }

    # ========================================================
    # 2. LOCK MEMORY TERMS INSIDE SENTENCE
    # ========================================================

    locked_source, locks = lock_memory_terms(
        source,
        memory
    )

    ai_item = dict(item)
    ai_item["source"] = locked_source

    for attempt in range(
        1,
        SINGLE_RETRIES + 1
    ):
        print(
            f"   🔄 Single attempt "
            f"{attempt}/{SINGLE_RETRIES}"
        )

        prompt = make_prompt(
            ai_item,
            previous_context,
            memory
        )

        if locks:
            prompt += make_memory_lock_prompt(locks)

        response = call_ollama(
            prompt,
            num_predict=512
        )

        if not response:
            print("   ⚠️ No response")
            continue

        result = extract_translation(
            response,
            item["index"]
        )

        if not result:
            print("   ⚠️ Invalid translation result")
            time.sleep(1)
            continue

        # ----------------------------------------------------
        # ตรวจ placeholder ก่อน restore
        # ----------------------------------------------------

        if locks and not validate_locked_terms(
            result["translation"],
            locks
        ):
            print(
                "   ⚠️ AI ทำ Memory placeholder หาย "
                "→ retry"
            )
            time.sleep(1)
            continue

        # ----------------------------------------------------
        # Restore Gold Memory
        # ----------------------------------------------------

        if locks:
            result["translation"] = restore_memory_terms(
                result["translation"],
                locks
            )
            result["memory"] = True
            result["memory_type"] = "locked_terms"

        print(
            f"   ✅ Translation: "
            f"{result['translation']}"
        )

        print(
            f"   🎯 Confidence: "
            f"{result['confidence']:.2f}"
        )

        return result

    return None

# ============================================================
# TRANSLATE BATCH
# ============================================================

def translate_batch(
    items,
    previous_context=None,
    memory=None
):
    expected_ids = [
        item["index"]
        for item in items
    ]

    final_results = {}
    ai_items = []
    memory_locks = {}

    # ========================================================
    # MEMORY-FIRST PREPROCESS
    # ========================================================

    for item in items:
        source = item["source"]

        # ----------------------------------------------------
        # 1. Exact sentence match
        # ----------------------------------------------------

        exact = find_exact_memory(
            source,
            memory
        )

        if exact:
            print(
                f"   🧠 MEMORY EXACT "
                f"[{item['index']}] "
                f"{source} → {exact['target_th']}"
            )

            final_results[item["index"]] = {
                "translation": exact["target_th"],
                "confidence": 1.0,
                "memory": True,
                "memory_type": "exact",
            }
            continue

        # ----------------------------------------------------
        # 2. Lock Memory terms
        # ----------------------------------------------------

        locked_source, locks = lock_memory_terms(
            source,
            memory
        )

        ai_item = dict(item)
        ai_item["source"] = locked_source

        if locks:
            memory_locks[item["index"]] = locks

            print(
                f"   🔒 MEMORY LOCK "
                f"[{item['index']}] "
                f"{len(locks)} terms"
            )

            for lock in locks:
                print(
                    f"      {lock['source']} "
                    f"→ {lock['target']}"
                )

        ai_items.append(ai_item)

    # ========================================================
    # ถ้าทุก subtitle มาจาก Exact Memory
    # ไม่ต้องเรียก Ollama
    # ========================================================

    if not ai_items:
        return final_results

    # ========================================================
    # AI BATCH
    # ========================================================

    prompt = make_batch_prompt(
        ai_items,
        previous_context,
        memory
    )

    all_locks = []

    for idx, locks in memory_locks.items():
        for lock in locks:
            all_locks.append(lock)

    if all_locks:
        # ลบ duplicate placeholder/source ถ้ามี
        prompt += make_memory_lock_prompt(all_locks)

    print(f"   🆔 Batch EXPECTED IDs: {expected_ids}")

    for attempt in range(
        1,
        MAX_RETRIES + 1
    ):
        print(
            f"   🔄 Batch attempt "
            f"{attempt}/{MAX_RETRIES}"
        )

        response = call_ollama(
            prompt,
            num_predict=2048
        )

        if not response:
            print("   ⚠️ No response")
            continue

        results = extract_batch_translations(
            response,
            [
                item["index"]
                for item in ai_items
            ]
        )

        if not results:
            print("   ⚠️ Invalid batch result (รวมถึง ID mismatch) → retry batch")
            time.sleep(1)
            continue

        # ----------------------------------------------------
        # Validate + restore
        # ----------------------------------------------------

        invalid_locked = False

        for item in ai_items:
            idx = item["index"]
            result = results.get(idx)

            if not result:
                invalid_locked = True
                break

            locks = memory_locks.get(idx, [])

            if locks:
                if not validate_locked_terms(
                    result["translation"],
                    locks
                ):
                    print(
                        f"   ⚠️ [{idx}] "
                        "AI ทำ Memory placeholder หาย"
                    )
                    invalid_locked = True
                    break

        if invalid_locked:
            time.sleep(1)
            continue

        for item in ai_items:
            idx = item["index"]
            result = results[idx]
            locks = memory_locks.get(idx, [])

            if locks:
                result["translation"] = restore_memory_terms(
                    result["translation"],
                    locks
                )
                result["memory"] = True
                result["memory_type"] = "locked_terms"

            final_results[idx] = result

        print(
            f"   ✅ Batch OK: "
            f"{len(final_results)}/{len(items)}"
        )

        for idx in sorted(final_results):
            result = final_results[idx]

            tag = (
                "MEMORY"
                if result.get("memory", False)
                else "AI"
            )

            print(
                f"      [{idx}] [{tag}] "
                f"{result['translation']} "
                f"(conf={result['confidence']:.2f})"
            )

        # Exact Memory + AI results ต้องครบ
        if set(final_results.keys()) == set(expected_ids):
            return final_results

        print(
            "   ⚠️ ผลลัพธ์ไม่ครบ "
            "→ retry"
        )

        time.sleep(1)

    return None

# ============================================================
# WRITE SRT
# ============================================================

def write_srt(
    path,
    subtitles,
    translations
):

    with open(
        path,
        "w",
        encoding="utf-8"
    ) as f:

        for item in subtitles:

            idx = item["index"]

            result = translations.get(
                idx
            )

            if isinstance(
                result,
                dict
            ):

                translation = result[
                    "translation"
                ]

            else:

                translation = result

            if not translation:

                translation = item[
                    "source"
                ]

            f.write(
                f"{idx}\n"
                f"{item['timecode']}\n"
                f"{translation}\n\n"
            )


# ============================================================
# FIND INPUT FILE
# ============================================================

def find_input_file():

    if not os.path.exists(
        INPUT_DIR
    ):

        os.makedirs(
            INPUT_DIR
        )

    files = [
        f
        for f in os.listdir(
            INPUT_DIR
        )
        if f.lower().endswith(".srt")
    ]

    if not files:

        print(
            f"❌ ไม่พบไฟล์ .srt "
            f"ใน {INPUT_DIR}/"
        )

        return None

    if len(files) == 1:

        return os.path.join(
            INPUT_DIR,
            files[0]
        )

    print(
        "\nพบไฟล์ SRT หลายไฟล์:"
    )

    for i, filename in enumerate(
        files,
        1
    ):

        print(
            f"{i}. {filename}"
        )

    while True:

        try:

            choice = int(
                input("เลือกไฟล์: ")
            )

            if (
                1 <= choice
                <= len(files)
            ):

                return os.path.join(
                    INPUT_DIR,
                    files[choice - 1]
                )

        except ValueError:

            pass

        print(
            "❌ กรุณาเลือกหมายเลข "
            "ให้ถูกต้อง"
        )


