# ============================================================
# MAIN
# ============================================================

def main():

    os.makedirs(
        OUTPUT_DIR,
        exist_ok=True
    )

    # โหลด Translation Memory ครั้งเดียวต่อการรัน
    memory = load_translation_memory()

    if memory:
        print(
            "🧠 Memory mode: ON "
            f"({len(memory)} entries)"
        )
    else:
        print("🧠 Memory mode: OFF / empty")

    input_file = find_input_file()

    if not input_file:
        return

    print(
        f"\n📄 Input: "
        f"{input_file}"
    )

    subtitles = parse_srt(
        input_file
    )

    print(
        f"📊 Total subtitles: "
        f"{len(subtitles)}"
    )

    # subtitles = [
    #     item
    #     for item in subtitles
    #     if START_SUBTITLE
    #     <= item["index"]
    #     <= END_SUBTITLE
    # ]

    print(
        f"🎯 Processing: "
        f"{len(subtitles)} subtitles"
    )

    translations = {}

    review_items = []

    # ========================================================
    # TRANSLATION
    # ========================================================

    for i in range(
        0,
        len(subtitles),
        BATCH_SIZE
    ):

        batch = subtitles[
            i:i + BATCH_SIZE
        ]

        print(
            f"\n🔄 Batch "
            f"{i + 1}-"
            f"{i + len(batch)}"
        )

        result = translate_batch(
            batch,
            memory=memory
        )

        # ----------------------------------------------------
        # Batch success
        # ----------------------------------------------------

        if result:

            for item in batch:

                idx = item[
                    "index"
                ]

                translation_result = (
                    result.get(idx)
                )

                translations[idx] = (
                    translation_result
                )

                quality = (
                    check_translation_quality(
                        item,
                        translation_result
                    )
                )

                if quality[
                    "needs_review"
                ]:

                    add_review_item(
                        review_items,
                        item,
                        translation_result,
                        quality
                    )

                    print(
                        f"   ⚠️ REVIEW "
                        f"[{idx}] "
                        f"{', '.join(quality['reasons'])}"
                    )

        # ----------------------------------------------------
        # Batch failed → Single
        # ----------------------------------------------------

        else:

            print(
                "⚠️ Batch failed"
            )

            print(
                "🔄 Falling back "
                "to single"
            )

            for item in batch:

                translation_result = (
                    translate_single(
                        item,
                        memory=memory
                    )
                )

                idx = item[
                    "index"
                ]

                if translation_result:

                    translations[idx] = (
                        translation_result
                    )

                quality = (
                    check_translation_quality(
                        item,
                        translation_result
                    )
                )

                if quality[
                    "needs_review"
                ]:

                    add_review_item(
                        review_items,
                        item,
                        translation_result,
                        quality
                    )

                    print(
                        f"   ⚠️ REVIEW "
                        f"[{idx}] "
                        f"{', '.join(quality['reasons'])}"
                    )

    # ========================================================
    # WRITE TRANSLATED SRT
    # ========================================================

    output_path = os.path.join(
        OUTPUT_DIR,
        "translated.srt"
    )

    write_srt(
        output_path,
        subtitles,
        translations
    )

    # ========================================================
    # WRITE REVIEW SRT
    # ========================================================

    review_path = os.path.join(
        OUTPUT_DIR,
        "review.srt"
    )

    write_review_srt(
        review_path,
        review_items
    )

    # ========================================================
    # SUMMARY
    # ========================================================

